(101348, 'The Bitter Truth Chocolate Bitters', 21, 'Original Bottling', 'Germany', 'Liqueurs & Bitters', 44, 'This bitter is created for use in both cocktails and food recipes. It is flavored with cocoa butter, dark chocolate, vanilla, cinnamon, gentian, wormwood, and other spices and botanicals. It is bottled at 44% ABV. . This bitter is created for use in both cocktails and food recipes. It is flavored with cocoa butter, dark chocolate, vanilla, cinnamon, gentian, wormwood, and other spices and botanicals. It is bottled at 44% ABV.', FALSE, '2025-01-07', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/b9018260-54a2-013c-303e-368953f0062c/the-bitter-truth-chocolate-bitters_original-1714074666.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100796, 'Alma Finca Orange Liqueur', 1, 'Original Bottling', 'Mexico', 'Liqueurs & Bitters', 40, 'Alma Finca is an orange liqueur from the Casa Lumbre portfolio known for other Mexican spirit brands such as Montelobos, Contraluz, Ancho Reyes, and more. It''s made with a combination of fruit and spices from the Yucatán Peninsula such as sweet & bitter orange peels, fresh Persian lime leaves, citrus blossoms, and local spices. A cooperative of local farmers harvests these ingredients seasonally from October-December. Each ingredient is then macerated individually for 5 days. Available in select markets beginning September 2023 with a national roll-out to follow. (SRP $34. Alma Finca is an orange liqueur from the Casa Lumbre portfolio known for other Mexican spirit brands such as Montelobos, Contraluz, Ancho Reyes, and more. It''s made with a combination of fruit and spices from the Yucatán Peninsula such as sweet & bitter orange peels, fresh Persian lime leaves, citrus blossoms, and local spices. A cooperative of local farmers harvests these ingredients seasonally from October-December. Each ingredient is then macerated individually for 5 days. Available in select markets beginning September 2023 with a national roll-out to follow. (SRP $34.99)', FALSE, '2025-02-20', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/f9b4db40-3e19-013c-044f-02f30fe0147f/alma-finca-orange-liqueur_original-1695681520.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100697, 'Senior''s Genuine Curaçao Liqueur', 1, 'Original Bottling', 'Netherlands Antilles', 'Liqueurs & Bitters', 40, 'N/A', FALSE, '2025-02-16', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/54f4d140-3757-013c-05fc-4e02651dd9f9/e5366cb8081e7dd5638e8e28cb05274d_original-1694934682.jpeg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=&mark-align=top,left&mark-pad=0&mark=https://s3.amazonaws.com/is.distiller.com/images/spirit_request_tags/liqueur_tag.png'),
(101063, 'Sagamore Spirit Amaro', 1, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 30, 'Sagamore Spirit Amaro is made with the distillery''s 95% rye distillate used to create its own rye whiskies. The bitter herbal liqueur was created to compliment its core line of rye whiskeys. Since the Maryland-based distillery also makes its own whiskey cherries, you can purchase all ingredients needed for a Black Manhattan from their visitor''s center in Baltimore. Bottled at 60 proof, it''s available at on- and off-premise accounts in CA, IL, NY, MD, MA, PA, TX, and DC beginning September 2023. (SRP $29.99). Sagamore Spirit Amaro is made with the distillery''s 95% rye distillate used to create its own rye whiskies. The bitter herbal liqueur was created to compliment its core line of rye whiskeys. Since the Maryland-based distillery also makes its own whiskey cherries, you can purchase all ingredients needed for a Black Manhattan from their visitor''s center in Baltimore. Bottled at 60 proof, it''s available at on- and off-premise accounts in CA, IL, NY, MD, MA, PA, TX, and DC beginning September 2023. (SRP $29.99)', FALSE, '2025-01-13', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/0416d6e0-3551-013c-d49e-1e7a740afb30/sagamore-spirit-amaro_original-1694716300.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
