(100557, 'Ezra Brooks Bourbon Cream (Discontinued)', 21, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 12.5, 'Ezra Brooks Bourbon Cream is made with Kentucky straight bourbon and real cream. It''s bottled at 25 proof. Note: As of spring 2023, this product has been reformulated and is now bottled at a higher proof. Look for that separate listing. Ezra Brooks Bourbon Cream is made with Kentucky straight bourbon and real cream. It''s bottled at 25 proof. Note: As of spring 2023, this product has been reformulated and is now bottled at a higher proof. Look for that separate listing.', FALSE, '2025-02-04', 'Cream', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/4b0e4060-fdba-0137-c18d-36593f95c4ff/ezra-brooks-bourbon-cream-discontinued_original-1684444039.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100858, 'Tempus Fugit Crème de Noyaux', 1, 'Original Bottling', 'Switzerland', 'Liqueurs & Bitters', 30, 'Tempus Fugit Crème de Noyaux is made from apricot and cherry pit kernels along with bitter almonds and other botanicals. Its red color is obtained from cochineal, an insect, so not vegan friendly. Tempus Fugit Crème de Noyaux is made from apricot and cherry pit kernels along with bitter almonds and other botanicals. Its red color is obtained from cochineal, an insect, so not vegan friendly. Bottled at 30% ABV.', FALSE, '2025-02-20', 'Nut', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/b91e4040-fa6c-0137-d154-622ff618e7d2/creme_de_noyaux_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100555, 'The Bitter Truth Violet Liqueur', 22, 'Original Bottling', 'Austria', 'Liqueurs & Bitters', 22, 'The Bitter Truth Violet Liqueur is made by infusing wild violet blossoms from the Alps into neutral spirit. This purple colored liqueur is sweetened and bottled at 20% ABV. The Bitter Truth Violet Liqueur is made by infusing wild violet blossoms from the Alps into neutral spirit. This purple colored liqueur is sweetened and bottled at 20% ABV.', FALSE, '2025-02-01', 'Floral', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/549086b0-f77b-0137-645d-62316d3e60b1/bitter_truth_violet_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101166, 'Tempus Fugit Liqueur de Violettes', 21, 'Original Bottling', 'Switzerland', 'Liqueurs & Bitters', 22, 'Tempus Fugit Liqueur de Violettes is made by Swiss distiller Oliver Matter using a mid-19th century recipe. Made with French violets, it is bottled at 22% ABV. Tempus Fugit Liqueur de Violettes is made by Swiss distiller Oliver Matter using a mid-19th century recipe. Made with French violets, it is bottled at 22% ABV. Note: the floral liqueur has a pink rather than a purple hue.', FALSE, '2025-01-23', 'Floral', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/b47762a0-f77a-0137-1b5f-1e9d998d78c7/tempus_fugit_liqueur_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101507, 'Giffard Crème de Violette', 22, 'Original Bottling', 'France', 'Liqueurs & Bitters', 16, 'Giffard Crème de Violette is made with the infusion of violet petals and the distillation of violet leaves. Bottled at 16% ABV. Giffard Crème de Violette is made with the infusion of violet petals and the distillation of violet leaves. Bottled at 16% ABV.', FALSE, '2025-02-27', 'Floral', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/069adc70-f774-0137-9660-764085eea602/giffard_creme_de_violette_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100890, 'G.E. Massenez Liqueur de Citron Vert et Gingembre', 1, 'Original Bottling', 'France', 'Liqueurs & Bitters', 23, 'N/A', FALSE, '2025-02-17', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/7c72c1c0-f0a5-0137-9ad1-064fbf4d241e/ge_massenez_citron_vert_et_gingembre_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=&mark-align=top,left&mark-pad=0&mark=https://s3.amazonaws.com/is.distiller.com/images/spirit_request_tags/liqueur_tag.png'),
(100595, 'St. George Spiced Pear Liqueur', 22, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 20, 'This pear liqueur from the famed Alameda, California producer uses its own Pear Brandy as the base. For that, they start with whole organic Bartlett pears, picked at the height of ripeness and distill in copper pot-stills. Then for the liqueur they add fruit juice and the proof gets brought down to 20% ABV. . This pear liqueur from the famed Alameda, California producer uses its own Pear Brandy as the base. For that, they start with whole organic Bartlett pears, picked at the height of ripeness and distill in copper pot-stills. Then for the liqueur they add fruit juice and the proof gets brought down to 20% ABV.', FALSE, '2025-02-09', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/74fa3c10-ed6d-0137-e09d-2acde9153164/st_george_spiced_pear_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
