(100222, 'Western Fruit Exchange Barrel Reserve Orange Liqueur', 22, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 40, 'Like the brand''s orange liqueur, this barrel-aged version starts off with brandy and fresh California oranges. Then it''s aged for six months in former bourbon barrels. Like the brand''s orange liqueur, this barrel-aged version starts off with brandy and fresh California oranges. Then it''s aged for six months in former bourbon barrels. Produced by California-based CalWise Spirits.', FALSE, '2025-02-07', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/47d3a910-e939-0137-1db1-1a624bbd8cfa/western_fruit_exchange_barrel_reserve_orange_liqueur_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100554, 'Western Fruit Exchange Orange Liqueur', 22, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 40, 'Western Fruit Exchange Orange Liqueur is made with brandy and fresh California oranges rather than dried orange peels which is the norm. Produced by California-based CalWise Spirits, it is bottled at 80 proof. Western Fruit Exchange Orange Liqueur is made with brandy and fresh California oranges rather than dried orange peels which is the norm. Produced by California-based CalWise Spirits, it is bottled at 80 proof.', FALSE, '2025-02-12', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/5496cf90-e938-0137-1db0-1a624bbd8cfa/western_fruit_exchange_orange_liqueur_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
