(100956, 'Patrón XO Cafe Incendio', 1, 'Original Bottling', 'Mexico', 'Liqueurs & Bitters', 30, 'Patrón XO Cafe Incendio is a chile-chocolate liqueur made with Patrón Silver Tequila, Mexican Arbol chile, and Criollo chocolate. It launched in October 2014 and is bottled at 60 proof. Patrón XO Cafe Incendio is a chile-chocolate liqueur made with Patrón Silver Tequila, Mexican Arbol chile, and Criollo chocolate. It launched in October 2014 and is bottled at 60 proof.', FALSE, '2025-02-20', 'Coffee', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/ecb06850-9fa8-0137-166a-0674cb1eff05/patro%2525CC%252581n-xo-cafe-incendio_original-1667870003.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100538, 'Passoã Passion Fruit Liqueur', 21, 'Original Bottling', 'France', 'Liqueurs & Bitters', 20, 'Passoã Passion Fruit Liqueur was first created in the mid 1980s using real passion fruit from Brazil. This red colored liqueur is bottled at 40 proof. Passoã Passion Fruit Liqueur was first created in the mid 1980s using real passion fruit from Brazil. This red colored liqueur is bottled at 40 proof.', FALSE, '2025-01-27', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/4e980de0-9e09-0137-1a0f-6abd99b0359b/passoa_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100598, 'Bittermens ''Elemakule Tiki Bitters', 21, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 44, 'This style of bitter is created with tropical cocktails in mind, created with tiki cocktail mixologist Brian Miller. It is inspired by flavors of Falernum liqueur and flavored with cinnamon, allspice, and other spices and botanicals. It is certified Kosher-Pareve (OU) and non-GMO, and bottled at 44% ABV. . This style of bitter is created with tropical cocktails in mind, created with tiki cocktail mixologist Brian Miller. It is inspired by flavors of Falernum liqueur and flavored with cinnamon, allspice, and other spices and botanicals. It is certified Kosher-Pareve (OU) and non-GMO, and bottled at 44% ABV.', FALSE, '2025-01-10', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/a8dcb360-9acf-0137-2b13-3a1a0b137692/bittermens-elemakule-tiki-bitters_original-1714074950.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100573, 'Whisper Creek Tennessee Sipping Cream', 21, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 20, 'Whisper Creek Tennessee Sipping Cream is produced by a husband and wife duo at Speakeasy Spirits in Nashville, TN. It uses a charcoal-mellowed Tennessee whiskey base as opposed to the more common white liquor base often used as a base in cream liqueurs. It is bottled at 20% ABV. . Whisper Creek Tennessee Sipping Cream is produced by a husband and wife duo at Speakeasy Spirits in Nashville, TN. It uses a charcoal-mellowed Tennessee whiskey base as opposed to the more common white liquor base often used as a base in cream liqueurs. It is bottled at 20% ABV.', FALSE, '2025-01-28', 'Cream', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/390c8ad0-947a-0137-81bf-1e7f94387c3d/whisper_creek_cream_liqueur_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
