(100683, 'Oak City Amaretto', 1, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 27, 'Oak City Amaretto was founded by Anthony Scalabrino, who based his product on his grandmother''s Sicilian amaretto recipe. Oak City shares a production space with Raleigh based Raleigh Rum Company. Oak City Amaretto was founded by Anthony Scalabrino, who based his product on his grandmother''s Sicilian amaretto recipe. Oak City shares a production space with Raleigh based Raleigh Rum Company. It is bottled at 27% ABV.', FALSE, '2025-01-16', 'Nut', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/e4bba070-9223-0137-5af4-7e7bb4e60166/oak_city_amaretto_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101227, 'B&B by Bénédictine', 21, 'Original Bottling', 'France', 'Liqueurs & Bitters', 40, 'B&B gets the name B&B as it is a blend of Bénédictine liqueur and brandy. Bénédictine is a made using a blend of 27 different plants and spices including juniper, myrrh, saffron, aloe and cinnamon. Dating back to the 1930s, this is essentially a pre-mixed and bottled cocktail. It is bottled at 40% ABV. B&B gets the name B&B as it is a blend of Bénédictine liqueur and brandy. Bénédictine is a made using a blend of 27 different plants and spices including juniper, myrrh, saffron, aloe and cinnamon. Dating back to the 1930s, this is essentially a pre-mixed and bottled cocktail. It is bottled at 40% ABV.', FALSE, '2025-01-28', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/c1f9e610-9204-0137-5adb-7e7bb4e60166/dom_b_and_b_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100105, 'Glayva Whisky Liqueur', 22, 'Original Bottling', 'Scotland', 'Liqueurs & Bitters', 35, 'Glayva Whisky Liqueur is a blend of Scotch malt whiskies, honey, cinnamon, other spices, and Mediterranean tangerines. Glayva is the phonetic pronunciation of the Gaelic phrase "gle mhath" meaning "very good. Glayva Whisky Liqueur is a blend of Scotch malt whiskies, honey, cinnamon, other spices, and Mediterranean tangerines. Glayva is the phonetic pronunciation of the Gaelic phrase "gle mhath" meaning "very good." Bottled at 70 proof.', FALSE, '2025-01-29', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/080e2900-9164-0137-42c3-466fe5dd92c0/glayva-whisky-liqueur_original-1675460189.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101092, 'Southern Comfort 80 Proof', 22, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 40, 'Introduced by the Sazerac Company in 2017, Southern Comfort 80 Proof is made with a mix of North American whiskeys owned by the company. Like the Original, it is flavored with fruits and spices. Introduced by the Sazerac Company in 2017, Southern Comfort 80 Proof is made with a mix of North American whiskeys owned by the company. Like the Original, it is flavored with fruits and spices.', FALSE, '2025-02-20', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/de61d430-9153-0137-69b8-36541f6036a6/southern_comfort_80_proof_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101175, 'Arrow Raspberry Schnapps', 21, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 15, 'Arrow Raspberry Schnapps is owned and produced by spirits brand Luxco, the producers of spirits like Rebel Yell, Ezra Brooks and Blood Oath whiskeys. The brand claims that Arrow is the 3rd best selling cordial line in the United States. It is bottled at 15% ABV. . Arrow Raspberry Schnapps is owned and produced by spirits brand Luxco, the producers of spirits like Rebel Yell, Ezra Brooks and Blood Oath whiskeys. The brand claims that Arrow is the 3rd best selling cordial line in the United States. It is bottled at 15% ABV.', FALSE, '2025-01-01', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/14918dc0-9149-0137-69b0-36541f6036a6/arrow_raspberry_schnapps_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
