(100402, 'Peychaud''s Barrel-Aged Bitters', 1, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 35, 'This is a limited edition release from Buffalo Trace of Peychaud''s signature aromatic bitters aged in ex-Sazerac rye barrels for 140 days, linking the two historic New Orleans brands in one product. It is bottled at 35% ABV. This is a limited edition release from Buffalo Trace of Peychaud''s signature aromatic bitters aged in ex-Sazerac rye barrels for 140 days, linking the two historic New Orleans brands in one product. It is bottled at 35% ABV.', FALSE, '2025-02-02', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/fd6ef020-69ce-0137-1cde-66558cfb182d/peychauds-barrel-aged-bitters_original-1714075182.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100346, 'Yukon Jack Original 100 Proof', 21, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 50, 'Yukon Jack is a high proof liqueur that originated as a product of Canada, and is now distributed by Sazerac Co. based in Kentucky. It is named after the 19th century settler Leroy Napoleon ''Jack'' McQuesten. It is a liqueur with flavors of whiskey and honey. Yukon Jack is a high proof liqueur that originated as a product of Canada, and is now distributed by Sazerac Co. based in Kentucky. It is named after the 19th century settler Leroy Napoleon ''Jack'' McQuesten. It is a liqueur with flavors of whiskey and honey.', FALSE, '2025-02-28', 'Other', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/d97c90d0-7120-0137-99c5-2eaa7c619d71/yukon-jack-original-100-proof_original-1700000628.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100808, 'Don Ciccio & Figli Amaro delle Sirene', 21, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 29, 'Don Ciccio & Figli Amaro delle Sirene is inspired by a recipe produced on the Amalfi Coast in Italy that was last made in 1931. Amaro delle Sirene is made from an infusion of 30 roots and herbs including eucalyptus, fruit, and licorice as well as chicory, chamomile, and gentiana lutea (yellow gentian). Don Ciccio & Figli Amaro delle Sirene is inspired by a recipe produced on the Amalfi Coast in Italy that was last made in 1931. Amaro delle Sirene is made from an infusion of 30 roots and herbs including eucalyptus, fruit, and licorice as well as chicory, chamomile, and gentiana lutea (yellow gentian). The bitter liqueur matures for 12 months in used French oak casks sourced from the Marisa Cuomo winery on the Amalfi Coast.', FALSE, '2025-02-02', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/af7aca20-6f80-0137-1d8b-0e7663ff5b56/amaro_delle_sirene_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101289, 'Nux Alpina Walnut Liqueur', 21, 'Original Bottling', 'Austria', 'Liqueurs & Bitters', 32, 'Nux Alpina Walnut Liqueur is made from fresh green Weinsberg walnuts. They are harvested in the summer near the Austrian village of Sankt Peter in der Au. The green walnuts are steeped in grape brandy for months with spices and Alpine botanicals added in the final month. After sweetening, the walnut liqueur is bottled at 32% ABV. Nux Alpina Walnut Liqueur is made from fresh green Weinsberg walnuts. They are harvested in the summer near the Austrian village of Sankt Peter in der Au. The green walnuts are steeped in grape brandy for months with spices and Alpine botanicals added in the final month. After sweetening, the walnut liqueur is bottled at 32% ABV.', FALSE, '2025-02-09', 'Nut', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/ea5b6980-69c9-0137-ece8-5e6cd974263c/nux_alpina_walnut_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100350, 'Amaro Angeleno', 21, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 23, 'N/A', FALSE, '2025-01-29', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/1544fa50-6726-0137-e125-1ad82cd382d9/data_original.?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=&mark-align=top,left&mark-pad=0&mark=https://s3.amazonaws.com/is.distiller.com/images/spirit_request_tags/liqueur_tag.png'),
(101008, 'Zwack Unicum', 1, 'Original Bottling', 'Hungary', 'Liqueurs & Bitters', 40, 'This herbal liqueur is based on a recipe originally created by József Zwack, the Royal Physician to the Habsburg Court for Emperor Joseph II in 1790. It has been commercialized by J. Zwack & Co. since the 1840s and after several stops and starts over the years, is now produced by the descendants of the Zwack family. It is a blend of more than 40 herbs and spices—some added during distillation, some macerated—and aged in oak for 6 months. Caramel color is added before bottling at 40% ABV. This herbal liqueur is based on a recipe originally created by József Zwack, the Royal Physician to the Habsburg Court for Emperor Joseph II in 1790. It has been commercialized by J. Zwack & Co. since the 1840s and after several stops and starts over the years, is now produced by the descendants of the Zwack family. It is a blend of more than 40 herbs and spices—some added during distillation, some macerated—and aged in oak for 6 months. Caramel color is added before bottling at 40% ABV.', FALSE, '2025-01-24', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/9bb70ed0-6876-0137-2fa6-52f9c9597028/zwack-unicum_original-1688422540.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100204, 'Pallini Limoncello', 1, 'Original Bottling', 'Italy', 'Liqueurs & Bitters', 26, 'This is a liqueur produced by a family distillery in the Amalfi Coast since 1875. It is made from Sfusato lemons that are infused in base spirit while still fresh from the vine and is GMO and gluten free as well as certified Kosher. It is bottled at 26% ABV. . This is a liqueur produced by a family distillery in the Amalfi Coast since 1875. It is made from Sfusato lemons that are infused in base spirit while still fresh from the vine and is GMO and gluten free as well as certified Kosher. It is bottled at 26% ABV.', FALSE, '2025-01-24', 'Fruit', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/7b795000-5bce-0137-dcf6-7a596f265984/pallini-limoncello_original-1693353008.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100017, 'Fee Brothers Aztec Chocolate Bitters', 1, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 2.55, 'This product is a bitter flavored with cacao beans, pepper, and spices for use in cocktails and cooking. . This product is a bitter flavored with cacao beans, pepper, and spices for use in cocktails and cooking.', FALSE, '2025-02-16', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/0b6788e0-5bcd-0137-dcf4-7a596f265984/fee-brothers-aztec-chocolate-bitters_original-1712685626.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100048, 'Combier Liqueur de Rose', 1, 'Original Bottling', 'France', 'Liqueurs & Bitters', 25, 'Combier Liqueur de Rose is made with hand-picked roses from the Loire. They are steeped in neutral alcohol made from sugar beets. No preservatives or artifical colors are used. . Combier Liqueur de Rose is made with hand-picked roses from the Loire. They are steeped in neutral alcohol made from sugar beets. No preservatives or artifical colors are used.', FALSE, '2025-01-28', 'Floral', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/65040c10-5984-0137-bc74-62eb924a007d/combier_liqueur_de_rose_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100726, 'Iris Liqueur', 22, 'Original Bottling', 'United States', 'Liqueurs & Bitters', 35, 'Iris Liqueur is made in Oregon by Elixir Craft Spirits. The floral liqueur is made from both the bloom and rhizome of the iris flower, both of which are highly aromatic. A variety of undisclosed botanicals are also used. . Iris Liqueur is made in Oregon by Elixir Craft Spirits. The floral liqueur is made from both the bloom and rhizome of the iris flower, both of which are highly aromatic. A variety of undisclosed botanicals are also used.', FALSE, '2025-01-23', 'Floral', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/0672ba00-5984-0137-d3d1-0aa995bed89c/elixir_craft_iris_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101174, 'ArchieMite Buttered Toast Spirit', 21, 'Original Bottling', 'Australia', 'Liqueurs & Bitters', 40, 'In an effort to capture the taste of Vegemite in a liqueur, Australian distillery Archie Rose created ArchieMite Buttered Toast Spirit. It took a massive 55 pounds of butter and 30 pounds of sourdough bread to bring this spirit to life. In an effort to capture the taste of Vegemite in a liqueur, Australian distillery Archie Rose created ArchieMite Buttered Toast Spirit. It took a massive 55 pounds of butter and 30 pounds of sourdough bread to bring this spirit to life. Only 3,000 bottles will be available at the distillery and online beginning May 8, 2019.', FALSE, '2025-01-05', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/4d7ddac0-54d5-0137-5af5-56a1fc7b810e/archiemite_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(101358, 'Galliano Ristretto', 22, 'Original Bottling', 'Italy', 'Liqueurs & Bitters', 30, 'Galliano Ristretto is an espresso liqueur made from two varieties of coffee beans. Robusta coffee beans from Kenya and India and Arabica coffee beans from Colombia and Brazil are used. Galliano Ristretto is an espresso liqueur made from two varieties of coffee beans. Robusta coffee beans from Kenya and India and Arabica coffee beans from Colombia and Brazil are used.', FALSE, '2025-01-07', 'Coffee', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/adf01420-5311-0137-f566-1ec5b905d13a/galliano_ristretto_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
(100559, 'Galliano L''Autentico', 22, 'Original Bottling', 'Italy', 'Liqueurs & Bitters', 42.3, 'Galliano L''Autentico is an herbal liqueur made using 30 herbs, plants, roots, barks, spices, and flower seeds. Although the recipe is secret, disclosed botanicals include anise, juniper, musk yarrow, star anise, lavender, peppermint, and vanilla. Featured ingredient in a Harvey Wallbanger cocktail along with vodka and orange juice. . Galliano L''Autentico is an herbal liqueur made using 30 herbs, plants, roots, barks, spices, and flower seeds. Although the recipe is secret, disclosed botanicals include anise, juniper, musk yarrow, star anise, lavender, peppermint, and vanilla. Featured ingredient in a Harvey Wallbanger cocktail along with vodka and orange juice.', FALSE, '2025-02-17', 'Herbs & Spices', 0, 'N/A', 'N/A', 'https://ip-distiller.imgix.net/images/spirits/e9388f30-5310-0137-5012-2a41c046831a/galliano_original.jpg?w=280&h=280&mark-w=70&mark-h=70&fit=crop&crop=right&mark-align=top,left&mark-pad=0&mark='),
